window.ScripturaLexicons.BDAG_PART_0374 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0374-01\" data-source=\"BDAG\" data-search=\"ὑψηλοφρονέω verbo ser orgulhoso; ser altivo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑψηλοφρονέω</td><td>verbo</td><td>ser orgulhoso; ser altivo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0374-02\" data-source=\"BDAG\" data-search=\"ὑψηλοφροσύνη, ης, ἡ substantivo feminino orgulho; altivez BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑψηλοφροσύνη, ης, ἡ</td><td>substantivo feminino</td><td>orgulho; altivez</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0374-03\" data-source=\"BDAG\" data-search=\"ὑψηλόφρων, ον, gen. ονος adjetivo orgulhoso; altivo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑψηλόφρων, ον, gen. ονος</td><td>adjetivo</td><td>orgulhoso; altivo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0374-04\" data-source=\"BDAG\" data-search=\"ὕψιστος, η, ον adjetivo; substantivado altíssimo; o Altíssimo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὕψιστος, η, ον</td><td>adjetivo; substantivado</td><td>altíssimo; o Altíssimo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0374-05\" data-source=\"BDAG\" data-search=\"ὕψος, ους, τό substantivo neutro altura; posição elevada; arrogância BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὕψος, ους, τό</td><td>substantivo neutro</td><td>altura; posição elevada; arrogância</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0374-06\" data-source=\"BDAG\" data-search=\"ὑψόω verbo elevar; exaltar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑψόω</td><td>verbo</td><td>elevar; exaltar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0374-07\" data-source=\"BDAG\" data-search=\"ὕψωμα, ατος, τό substantivo neutro altura; mundo superior; arrogância BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὕψωμα, ατος, τό</td><td>substantivo neutro</td><td>altura; mundo superior; arrogância</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0374-08\" data-source=\"BDAG\" data-search=\"φαγεῖν, φάγομαι remissão v. ἐσθίω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φαγεῖν, φάγομαι</td><td>remissão</td><td>v. ἐσθίω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0374-09\" data-source=\"BDAG\" data-search=\"φάγος substantivo masculino glutão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φάγος</td><td>substantivo masculino</td><td>glutão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0374-10\" data-source=\"BDAG\" data-search=\"φαιλόνης, ου, ὁ substantivo masculino manto; capa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φαιλόνης, ου, ὁ</td><td>substantivo masculino</td><td>manto; capa</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0374-11\" data-source=\"BDAG\" data-search=\"φαίνω verbo brilhar; aparecer; manifestar-se; parecer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φαίνω</td><td>verbo</td><td>brilhar; aparecer; manifestar-se; parecer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0374-12\" data-source=\"BDAG\" data-search=\"Φάλεκ nome próprio masculino indeclinável Pelegue BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Φάλεκ</td><td>nome próprio masculino indeclinável</td><td>Pelegue</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0374-13\" data-source=\"BDAG\" data-search=\"φανεροποιέω verbo revelar; dar a conhecer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φανεροποιέω</td><td>verbo</td><td>revelar; dar a conhecer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0374-14\" data-source=\"BDAG\" data-search=\"φανερός, ά, όν adjetivo; substantivado manifesto; visível; público BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φανερός, ά, όν</td><td>adjetivo; substantivado</td><td>manifesto; visível; público</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0374-15\" data-source=\"BDAG\" data-search=\"φανερόω verbo manifestar; revelar; dar a conhecer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φανερόω</td><td>verbo</td><td>manifestar; revelar; dar a conhecer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0374-16\" data-source=\"BDAG\" data-search=\"φανερῶς advérbio publicamente; distintamente; claramente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φανερῶς</td><td>advérbio</td><td>publicamente; distintamente; claramente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0374-17\" data-source=\"BDAG\" data-search=\"φανέρωσις, εως, ἡ substantivo feminino manifestação; proclamação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φανέρωσις, εως, ἡ</td><td>substantivo feminino</td><td>manifestação; proclamação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0374-18\" data-source=\"BDAG\" data-search=\"φανός, οῦ, ὁ substantivo masculino luz portátil; lâmpada; lanterna BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φανός, οῦ, ὁ</td><td>substantivo masculino</td><td>luz portátil; lâmpada; lanterna</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0374-19\" data-source=\"BDAG\" data-search=\"Φανουήλ, ὁ nome próprio masculino indeclinável Fanuel BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Φανουήλ, ὁ</td><td>nome próprio masculino indeclinável</td><td>Fanuel</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0374-20\" data-source=\"BDAG\" data-search=\"φαντάζω verbo tornar visível; aparecer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φαντάζω</td><td>verbo</td><td>tornar visível; aparecer</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0374-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑψηλοφρονέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑψηλοφρονέω</span> (<span class=\"greek\">ὑψηλόφρων</span> ‘altivo’; Pollux 9, 145; escólio sobre Pind., P. 2, 91; escólio sobre Eur., Hippol. 728; Phot. e Suda s.v. <span class=\"greek\">ὑψαυχεῖν</span>; B-D-F §119, 5; Rob. 163 n.) ser orgulhoso, altivo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:20</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:17</a>.—DELG s.v. <span class=\"greek\">ὕψι</span> e <span class=\"greek\">φρήν</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0374-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑψηλοφροσύνη, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑψηλοφροσύνη</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (Physiogn. II 225, 6; Hesych. s.v. <span class=\"greek\">φυσίωσις</span>; Leontius de Neap. [VII d.C.] 28 p. 61, 5; 10 HGelzer [1893]) orgulho, altivez Hm 8:3; Hs 9, 22, 3.—DELG s.v. <span class=\"greek\">ὕψι</span> e <span class=\"greek\">φρήν</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0374-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑψηλόφρων, ον, gen. ονος</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑψηλόφρων</span>, <span class=\"greek\">ον</span>, gen. <span class=\"greek\">ονος</span> (Eur., Pla.; Cass. Dio 72, 8, 3=‘de espírito elevado, brioso’) orgulhoso, altivo (assim Pollux 9, 147; Eustath., Opuscula 23, 60 p. 209, 96; o adv. Pel.-Leg. 22, 31) Hs 8, 9, 1.—DELG s.v. <span class=\"greek\">ὕψι</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0374-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὕψιστος, η, ον</h1><div class=\"entry-meta\"><span>adjetivo; substantivado</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὕψιστος</span>, <span class=\"greek\">η</span>, <span class=\"greek\">ον</span> (Pind., Aeschyl.+; empréstimo na literatura rabínica) superl. do adv. <span class=\"greek\">ὕψι</span>; nenhum positivo em uso</p><p class=\"entry-text\">① Relativo a ser o mais alto em sentido espacial, altíssimo (Diog. L. 8, 31 <span class=\"greek\">ὁ</span> <span class=\"greek\">ὕψιστος</span> <span class=\"greek\">τόπος</span>, segundo Pitágoras, é o lugar ao qual Hermes conduz as almas puras) <span class=\"greek\">τὰ</span> <span class=\"greek\">ὕψιστα</span> as mais altas alturas=céu (Job 16:19; Ps 148:1; PsSol 18:10; JosAs 22:9=<span class=\"hebrew\" dir=\"rtl\">מְרוֹמִים</span>; cf. 1QM 14, 14; 17, 8) <span class=\"greek\">ὡσαννὰ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ὑψίστοις</span> concede salvação, (tu que estás) no mais alto céu Mt 21:9; Mk 11:10 (Goodsp., Probs. 34f). <span class=\"greek\">δόξα</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὑψ</span>. Lk 2:14 (oposto a <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">γῆς</span>); 19:38 (com <span class=\"greek\">ἐν</span> <span class=\"greek\">οὐρανῷ</span>, que significa o mesmo). <span class=\"greek\">ὁ</span> <span class=\"greek\">ὕψιστος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὑψίστοις</span> o Altíssimo no mais alto (céu) 1 Cl 59:3 (cf. Is 57:15).</p><p class=\"entry-text\">② Relativo a ser o mais elevado em condição, <span class=\"greek\">ὁ</span> <span class=\"greek\">ὕψιστος</span> o Altíssimo, de Deus, distinguido de divindades inferiores e outros objetos de devoção cultual (<span class=\"greek\">Ζεὺς</span> <span class=\"greek\">ὕψιστος</span>: Pind., N. 1, 60 [90]; 11, 2; Aeschyl., Eum. 28; CIG 498; 503; 1869 al.; Aristonous, em Coll. Alex. 1, 7 p. 163 [ACook, Zeus I/2, 1925, 876–89; CRoberts, TSkeat e ANock, The Gild of Zeus Hypsistos: HTR 29, ’36, 39–88, o texto gr. de Sb 7835 citado neste artigo não foi reimpresso em Nock, Essays: v. New Docs 1, 28]. <span class=\"greek\">θεὸς</span> <span class=\"greek\">ὕψιστος</span>: inscr. de Chipre em BCH 20, 1896 p. 361; Sb 589 [II a.C.]; 1323, 1 [II d.C.]; OGI 378, 1 [I d.C.] <span class=\"greek\">θεῷ</span> <span class=\"greek\">ἁγίω</span> <span class=\"greek\">ὑψίστῳ</span>; 755, 1f <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἁγιωτάτου</span> [<span class=\"greek\">θεοῦ</span> <span class=\"greek\">ὑψί</span>]<span class=\"greek\">στου</span> <span class=\"greek\">σωτῆρος</span>; 756, 3–4 <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἁγιατάτου</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ὑψίστου</span>: PGM 4, 1068 <span class=\"greek\">ἱερὸν</span> <span class=\"greek\">φῶς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὑψίστου</span> <span class=\"greek\">θεοῦ</span>; 5, 46; 12, 63; 71; New Docs 1, 25 n.º 5. Ísis como <span class=\"greek\">ὑψ</span>. <span class=\"greek\">θεός</span>: IAndrosIsis [Kyrene] 7 p. 129 Peek. Também simplesmente <span class=\"greek\">Ὕψιστος</span> CIG 499; 502. Outras inscr. e papiros New Docs 1, 25–28. Sobre as comunidades sincretistas dos <span class=\"greek\">σεβόμενοι</span> <span class=\"greek\">θεὸν</span> <span class=\"greek\">ὕψιστον</span> cf. ESchürer, SBBerlAk 1897, 200–225, History III 169; FCumont, Hypsistos: Suppl. à la Rev. de l’instruction publique en Belgique 1897, Pauly-W. s.v. Hypsistos; Kl. Pauly II 129f; APlassart, Mélanges Holleaux 1913, 201ff; Clemen2 58–60. Não se pode estabelecer se há influência israelita, pois o emprego de <span class=\"greek\">ὕψιστος</span> permeia os textos greco-romanos [v. bibliografia citada acima e Nock, Essays I 414–43; v. também New Docs 1, 25–29], mas ‘Deus Altíssimo’ certamente ocupa lugar firme na experiência israelita, e o uso no AT [LXX] explicaria seu emprego no NT, aliado à possibilidade semântica proporcionada pela formulação politeísta. Exemplos de uso através de fronteiras culturais incluem: OGI 96, 5–7 [III/II a.C.]; APF 5, 1913, p. 163 [29 a.C.] <span class=\"greek\">θεῷ</span> <span class=\"greek\">μεγάλῳ</span> <span class=\"greek\">μεγάλῳ</span> <span class=\"greek\">ὑψίστω</span>; En, TestAbr, Test12Patr, JosAs; ApcEsdr1, 2 p. 24, 5 Tdf.; ApcZeph; Philo, In Flacc. 46, Ad Gai. 278; 317; Jos., Ant. 16, 163; Ar. 15, 1; Just., D. 32, 3; 124, 1; as orações judaicas por vingança de Reneia [Dssm., LO 352ff=LAE 416; SIG 1181, 1f]; CIJ I, 690, 727–30; SibOr 3, 519; 719; Ezek. Trag. 239 [em Eus., PE 9, 29, 14]; Philo Epicus: 729 Fgm. 3, 2 Jac. [Eus., PE 9, 24]; <span class=\"greek\">ὁ</span> <span class=\"greek\">μέγας</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὕψ</span>. <span class=\"greek\">θεός</span> Hippol., Ref. 9, 15, 1; ANock, CRoberts, TSkeat, HTR 29, 36, 39–88). <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ὕψ</span>. (cf. Theoph. Ant. 2, 3 [p. 100, 1]) Mk 5:7; Lk 8:28; Ac 16:17; Hb 7:1 (Gen 14:18). <span class=\"greek\">τὸν</span> <span class=\"greek\">ὕψ</span>. <span class=\"greek\">θεόν</span> GJs 24:1. <span class=\"greek\">ὁ</span> <span class=\"greek\">ὕψ</span>. (TestAbr A 9 p. 87, 10 [Stone p. 22]; freq. Test12Patr; JosAs 8:10; ApcEsdr 1:2; Just., D. 32, 3. <span class=\"greek\">ἡ</span> <span class=\"greek\">δύναμις</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὑ</span>. Hippol., Ref. 6, 35, 7) Ac 7:48; 1 Cl 29:2 (Dt 32:8); 45:7; 52:3 (Ps 49:14). <span class=\"greek\">ὁ</span> <span class=\"greek\">μόνος</span> <span class=\"greek\">ὕψ</span>. 59:3 (v. 1 acima, final). Também sem art. (En 10:1; TestSim 2:5; TestLevi 8:15; Just., D. 124, 1 e 4; Mel., P. 98, 752 [com art. Ps 17:14]) <span class=\"greek\">ὕψ</span>. Lk 1:35, 76. <span class=\"greek\">υἱὸς</span> <span class=\"greek\">ὑψίστου</span> v. 32 (de Cristo; sobre a associação de <span class=\"greek\">υἱὸς</span> <span class=\"greek\">ὑψίστου</span> e <span class=\"greek\">υἱὸς</span> <span class=\"greek\">θεοῦ</span> [v. 34] cf. o texto aramaico 4QpsDan Aa [=4Q 246], JFitzmyer, NTS 20, ’73/74, 382–407 [esp. 391–94]); também GJs 11:3; no pl. de seres humanos (cf. Sir 4:10) Lk 6:35. <span class=\"greek\">πατὴρ</span> <span class=\"greek\">ὕψ</span>. IRo ins.—DNP V 821–23. DELG s.v. <span class=\"greek\">ὕψι</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0374-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὕψος, ους, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὕψος</span>, <span class=\"greek\">ους</span>, <span class=\"greek\">τό</span> (Aeschyl., Hdt.+; inscr., papiros, LXX, pseudepígr.; Philo; Jos., C. Ap. 2, 119 <span class=\"greek\">ὕψ</span>., <span class=\"greek\">πλάτος</span> al.; Just., D. 39, 5; Mel., P. [edições e mss. oscilam no uso do pl. <span class=\"greek\">ὕψη</span> ou <span class=\"greek\">ὕψηλα</span>]) ‘altura’.</p><p class=\"entry-text\">① Extensão ou distância para cima, altura</p><p class=\"entry-text\">ⓐ De dimensão 1 Cl 49:4 (talvez sentido b). Com outras dimensões (<span class=\"greek\">τὸ</span> <span class=\"greek\">μῆκος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πλάτος</span>) Rv 21:16. (<span class=\"greek\">πλάτος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μῆκος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">βάθος</span>) Eph 3:18 (<span class=\"greek\">βάθος</span> 1).—Pl. <span class=\"greek\">ἀναφέρεσθαι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ὕψη</span> IEph 9:1.</p><p class=\"entry-text\">ⓑ De lugar, altura=lugar elevado (SibOr 8, 235), principalmente=céu (Ps 17:17 <span class=\"greek\">ἐξ</span> <span class=\"greek\">ὕψους</span>; 101:20; TestJob 15:1 <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὕψει</span>; Just., D. 39, 5; Stephan. Byz. s.v. <span class=\"greek\">Λαοδίκεια</span>: <span class=\"greek\">ἀφ</span>’ <span class=\"greek\">ὕψους</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεός</span>) Lk 1:78 (<span class=\"greek\">ἀνατολή</span> 3); 24:49; Eph 4:8 (Ps 67:19). <span class=\"greek\">τὰ</span> <span class=\"greek\">ὕψη</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">οὐρανῶν</span> 1 Cl 36:2 (Diod S 4, 7, 4 <span class=\"greek\">ὕψος</span> <span class=\"greek\">οὐράνιον</span>; Aesop, Fab. 397b H. <span class=\"greek\">τὰ</span> <span class=\"greek\">οὐράνια</span> <span class=\"greek\">ὕψη</span>).—<span class=\"greek\">τὰ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὕψεσι</span> como algo diferente de <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">οὐρανοῖς</span> Dg 7:2 (oposto a <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">βάθεσι</span>).</p><p class=\"entry-text\">② Uma posição de elevada condição, posição elevada (de categoria Herodian 1, 13, 6; 1 Macc 1:40; 10:24.—De grau: Pla., Ep. 7, 351e <span class=\"greek\">ὕψος</span> <span class=\"greek\">ἀμαθίας</span> o ‘cúmulo’ da ignorância; Ps.-Aristot., De Mundo 6; Plut., Publ. 100 [6, 5]; Jos., Ant. 8, 126 <span class=\"greek\">ὕψος</span> <span class=\"greek\">εὐδαιμονίας</span>) Js 1:9 (oposto a <span class=\"greek\">ταπεινός</span> e <span class=\"greek\">ταπείνωσις</span> como em TestAbr B 7 p. 111, 21 [Stone p. 70]) <span class=\"greek\">τὸν</span> <span class=\"greek\">ποιοῦντα</span> <span class=\"greek\">ταπεινοὺς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ὕψος</span> aquele que exalta os humildes (a menos que <span class=\"greek\">εἰς</span> <span class=\"greek\">ὕψ</span>. signifique ‘ereto’, como Apollod. [II a.C.]: 244 Fgm. 107d [=107e] Jac.) 1 Cl 59:3 (Job 5:11).</p><p class=\"entry-text\">③ Uma elevada opinião de si mesmo, orgulho, arrogância (PsSol 17:6) D 5:1. <span class=\"greek\">ὕψος</span> <span class=\"greek\">δυνάμεως</span> arrogância em posição influente B 20:1.—JKühn, <span class=\"greek\">Υψος</span> ’41.—DELG s.v. <span class=\"greek\">ὕψι</span>. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0374-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑψόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑψόω</span> fut. <span class=\"greek\">ὑψώσω</span>; 1 aor. <span class=\"greek\">ὕψωσα</span>. Pass.: 1 fut. <span class=\"greek\">ὑψωθήσομαι</span>; 1 aor. <span class=\"greek\">ὑψώθην</span>; 1 part. perf. <span class=\"greek\">ὑψωμένος</span> Jer 17:12 (de <span class=\"greek\">ὕψι</span> ‘nas alturas’, formado como seu oposto <span class=\"greek\">ταπεινόω</span>; desde Hippocr.; também SIG 783, 45 [I a.C.]; PBrem 14, 7 [II d.C.]; LXX; pseudepígr.; Jos., Bell. 1, 146; 3, 171; Mel.)</p><p class=\"entry-text\">① Elevar espacialmente, levantar, erguer ao alto <span class=\"greek\">τινά</span> ou <span class=\"greek\">τί</span> alguém ou algo (Batrach. 81; TestAbr A 9 p. 87, 14 [Stone p. 22]; 10, p. 87, 17 [St. p. 22]; JosAs 12:3; PGM 4, 2395; 2989f) <span class=\"greek\">Μωϋσῆς</span> <span class=\"greek\">ὕψωσεν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ὄφιν</span> Moisés levantou a serpente, fixando-a numa haste à vista de todos J 3:14a. Da mesma maneira Cristo é levantado na cruz v. 14b (Mel., P. 95, 727; cf. Artem. 4, 49 <span class=\"greek\">ὑψηλότατον</span> <span class=\"greek\">εἶναι</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἐσταυρωμένον</span>; 1, 76 p. 69, 11; 2, 53; Ps.-Callisth. 2, 21, 26 <span class=\"greek\">ἔσεσθε</span> <span class=\"greek\">περιφανεῖς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">διάσημοι</span> <span class=\"greek\">πᾶσιν</span> <span class=\"greek\">ἀνθρώποις</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">σταυρὸν</span> <span class=\"greek\">κρεμασθέντες</span> [um jogo de palavras com uma expressão ambígua que, empregando a palavra ‘eminente’, pode significar tanto posição social quanto ser levantado numa cruz à vista de todos]); para J este ‘levantamento’ não deve ser separado da ‘exaltação’ ao céu, visto que a exaltação celestial pressupõe a terrena 8:28; 12:32 (<span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γῆς</span>; CTorrey, JBL 51, ’32, 320–22)—12:34 (Hdb. sobre J 3:14; CLattey, Le verbe <span class=\"greek\">ὕψ</span>. dans St. Jean: RSR 3, 1912, 597f; CLindeboom, ‘Verhoogd worden’ in Joh. 3:14: GereformTT 15, 1915, 491–98; MBlack, Aramaic Approach3 141; OCullmann, TZ 4, ’48, 365f; WThüsing, Die Erhöhung und Verherrlichung Jesu im J, ’60; JSchaberg, Daniel 7:12 and the NT Passion-Resurrection Predictions, NTS 31, ’85, 208–22 [o equivalente aramaico de <span class=\"greek\">ὑψωθῆναι</span> é <span class=\"hebrew\" dir=\"rtl\">אזדקיף</span> , que significa tanto ‘ser exaltado’ quanto ‘ser crucificado ou enforcado’, 217f]). <span class=\"greek\">τῇ</span> <span class=\"greek\">δεξιᾷ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ὑψωθείς</span> exaltado (ao céu) pelo Poder (<span class=\"greek\">δεξιός</span> 1b, final) de Deus Ac 2:33. Marcam a transição para o sentido 2 as passagens em que <span class=\"greek\">ἕως</span> <span class=\"greek\">οὐρανοῦ</span> <span class=\"greek\">ὑψωθῆναι</span> é metáfora de ser coroado com as mais altas honras (cf. PsSol 1:5; ApcEsdr 4:32) Mt 11:23; Lk 10:15.</p><p class=\"entry-text\">② Promover o aumento de honra, fama, posição, poder ou fortuna, exaltar, extensão fig. de 1 (Polyb. 5, 26, 12 [oposto a <span class=\"greek\">ταπεινοῦν</span>]; Plut., Mor. 103e; LXX). Deus exalta <span class=\"greek\">τινά</span> alguém (TestJos 1:7; 18:1) <span class=\"greek\">ταπεινούς</span> (cf. Ezk 21:31; EpArist 263) Lk 1:52; cf. Js 4:10; 1 Pt 5:6. Pass. (TestReub 6:5; SibOr 3, 582) Mt 23:12b; Lk 14:11b; 18:14b; 2 Cor 11:7.—<span class=\"greek\">τοῦτον</span> (i.e., Cristo) <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">ἀρχηγὸν</span> <span class=\"greek\">ὕψωσεν</span> Deus o exaltou como líder Ac 5:31. Deus <span class=\"greek\">τὸν</span> <span class=\"greek\">λαὸν</span> <span class=\"greek\">ὕψωσεν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">γῇ</span> <span class=\"greek\">Αἰγύπτου</span> tornou grande o povo (em número e poder) no Egito 13:17.—<span class=\"greek\">ὑψοῦν</span> <span class=\"greek\">ἐαυτόν</span> exaltar-se, considerar-se melhor que os outros (TestJos 17:8; Hippol., Ref. 10, 14, 6; cf. ParJer 6:23 <span class=\"greek\">ὑψώθη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">καρδία</span> <span class=\"greek\">ὑμῶν</span>) Mt 23:12a; Lk 14:11a; 18:14a; B 19:3; D 3:9; Hm 11:12; Hs 9, 22, 3.—DELG s.v. <span class=\"greek\">ὕψι</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0374-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὕψωμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὕψωμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (de <span class=\"greek\">ὕψι</span> por meio de <span class=\"greek\">ὑψόω</span>; Plut., Mor. 782d; Sext. Emp., Math. 5, 33; 35; LXX; TestJob 41, 4; Philo, Praem. 2; Ps.-Phoc. 73; SibOr 8, 234; o sentido ‘extensão linear’ [‘altura’] não se encontra em nossa literatura)</p><p class=\"entry-text\">① Como termo astronômico (cf. o termo técnico ‘exaltação’ Plut., Mor. 149a; Ptolem., Apotel. 1, 20, 1ff; freq. Vett. Val.; PLond 110, 14; Cat. Cod. Astr. XII 102, 25. Neugebauer/Hoesen, glossário p. 199) o espaço acima do horizonte, o mundo superior (que seria o domínio de muitas forças transcendentes) Ro 8:39 (oposto a <span class=\"greek\">βάθος</span>, q.v. 1 e v. Rtzst., Poim. 80; WKnox, St. Paul and the Church of the Gentiles ’39, 106f).—OGerhardt, D. Stern des Messias 1922, 15. <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ὑψωμάτων</span> GJs 6:2.</p><p class=\"entry-text\">② Aquilo que se ergue arrogantemente, arrogância, <span class=\"greek\">πᾶν</span> <span class=\"greek\">ὕψωμα</span> <span class=\"greek\">ἐπαιρόμενον</span> tudo o que se levanta, prov.=todo orgulho (todo obstáculo arrogante NRSV) que se levanta contra ele 2 Cor 10:5 (Euthym.: <span class=\"greek\">ὑψηλοφρονία</span>. Mas Chrysost. MPG LXI, 545 explica-o empregando <span class=\"greek\">πύργωμα</span>, que significaria algo como ‘fortaleza altaneira’; cf. PPetr III, 46, 3, 11 <span class=\"greek\">τοὺς</span> <span class=\"greek\">ἐπαρθέντας</span> <span class=\"greek\">τοίχους</span>; TestJob 41:4 <span class=\"greek\">ἐποίησεν</span> <span class=\"greek\">ἑαυτὸν</span> <span class=\"greek\">ἀθρόως</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ὕψωμα</span> ‘autoengrandecimento’).—DELG s.v. <span class=\"greek\">ὕψι</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0374-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαγεῖν, φάγομαι</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φαγεῖν</span>, <span class=\"greek\">φάγομαι</span> v. <span class=\"greek\">ἐσθίω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0374-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φάγος</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φάγος</span> (assim acentuado por Hesychius [s.v. <span class=\"greek\">τρώκτης</span>] e Eustath., Od. 1630, 15, embora Herodian Gr. I 140, 4 prefira <span class=\"greek\">φαγός</span> [v. PKatz, TLZ 83, ’58, 316]), <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Zenob. Paroem. [II d.C.] 1, 73) glutão com <span class=\"greek\">οἰνοπότης</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:34</a>.—V. <span class=\"greek\">ἐσθίω</span>. DELG s.v. <span class=\"greek\">φαγεῖν</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0374-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαιλόνης, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φαιλόνης</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> deve ser grafado assim (B-D-F §25) em oposição aos grandes unciais e edições críticas, que trazem <span class=\"greek\">φελόνης</span> (PFay 347 [II d.C.]). Parece ser empréstimo lat. (paenula; v. Hahn p. 10, 8; EFraenkel, ZVS 42, 1909, 115, 1; ESchwyzer, MusHelv 3, ’46, 50–52; mas v. B. abaixo), também na literatura rabínica em várias grafias. Sua forma original era <span class=\"greek\">φαινόλας</span> (Rhinthon [III a.C.], Com. Graec. Fgm. 7 Kaibel [em Pollux 7, 61]) ou <span class=\"greek\">φαινόλης</span> (Epict. 4, 8, 34; Artem. 2, 3; 5, 29; Athen. 3, 97e; POxy 736, 4; 1737, 9; 15; PGiss 10, 21; PHamb 10, 19 [II a.C.]; Gignac I 100), também <span class=\"greek\">φαινόλιον</span> (POxy 531, 14 [II d.C.]; 936, 18; 19). Destas, por metátese (v. CLobeck, Pathologiae Sermonis Graeci Elementa I 1853, 514; W-S. §5, 18; B-D-F §32, 2; Mlt-H. 81; 106; 155), proveio <span class=\"greek\">φαιλόνης</span> (que ainda pode ser citado pelo menos em sua forma dim. <span class=\"greek\">φαιλόνιον</span> [-<span class=\"greek\">ώνιον</span>]: POxy 933, 30; PGiss 12, 4 [II d.C.]; BGU 816, 24 [III d.C.]; cf. gr. mod. <span class=\"greek\">φελόνι</span>) manto (POxy 531, 14 <span class=\"greek\">τὰ</span> <span class=\"greek\">ἱμάτια</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">λευκὰ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">δυνάμενα</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πορφυρῶν</span> <span class=\"greek\">φορεῖσθαι</span> <span class=\"greek\">φαινολίων</span>. Igualmente Epict.; Athen., loc. cit. Em vista destas passagens, exclui-se a tradução ‘valise’; v. Field, Notes 217f, citado em M-M; exclui-se também a interpretação no sentido de <span class=\"greek\">διφθέρα</span>, a capa de couro para rolos de papiro) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:13</a> (sobre o assunto v. POxy 1489 [III d.C.] <span class=\"greek\">τὸ</span> <span class=\"greek\">κιθώνιν</span> [=<span class=\"greek\">χιτώνιον</span>] <span class=\"greek\">ἐπιλέλησμαι</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">Τεκοῦσαν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">πυλῶνα</span>. <span class=\"greek\">πέμψον</span> <span class=\"greek\">μοι</span>).—V. B. 417, onde <span class=\"greek\">φαινόλα</span> é tratada como a forma original da qual se tomou por empréstimo o lat. paenula, e não vice-versa; v. também Mlt-H. 106.—Frisk. DELG s.v. <span class=\"greek\">φαίνω</span> A. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0374-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαίνω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φαίνω</span> (Hom.+) fut. 3 pl. <span class=\"greek\">φανοῦσιν</span> Da 12:3; 1 aor. <span class=\"greek\">ἔφανα</span> (B-D-F §72; Mlt-H. 214f), subj. 3 sg. <span class=\"greek\">φάνῃ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.8.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 8:12</a>; 18:23; 2 perf. <span class=\"greek\">πέφηνα</span> (Tat.). Méd.: aor. subj. 3 sg. <span class=\"greek\">φάνηται</span> (Just., A I, 7, 4). Pass.: imperf. <span class=\"greek\">ἐφαινόμην</span>; 2 fut. <span class=\"greek\">φανήσομαι</span> (2 Macc 6:27; v. B-D-F §79; Mlt-H. 262; o mais antigo <span class=\"greek\">φανοῦμαι</span> somente na LXX—citação <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:18</a>); 2 aor. <span class=\"greek\">ἐφάνην</span>; perf. 3 sg. <span class=\"greek\">πέφανται</span> e inf. <span class=\"greek\">πέφανθαι</span> (Just.)</p><p class=\"entry-text\">① Brilhar ou produzir luz, brilhar</p><p class=\"entry-text\">ⓐ Na voz at., exceto GJs 16:2 v.l. (v. deStrycker ad loc.), em nossa literatura somente intr., brilhar, dar luz, ser luminoso (Aristoph., Nub. 586 do sol; Pla., Tim. 39b; Theocr. 2, 11 da lua; Gen 1:15, 17; En 104:2; 2; TestJob 31:5 das estrelas; SibOr 5, 522; 8, 203) sol Rv 1:16. Sol e lua 21:23 (ApcMos 31); lua PtK 2 p. 14, 27; Dg 7:2. Uma lâmpada (1 Macc 4:50) 2 Pt 1:19; em linguagem figurada J 5:35 (numa comparação Theoph. Ant. 2, 13 [p. 134, 4]). Luz Rv 18:23 (<span class=\"greek\">φάνῃ</span> edições modernas; <span class=\"greek\">φανῇ</span> t.r.) em linguagem figurada J 1:5; 1J 2:8. Dia e noite brilham, na medida em que o sol, ou a lua e as estrelas, dão sua luz Rv 8:12 (texto <span class=\"greek\">φάνῃ</span>; v.l. <span class=\"greek\">φανῇ</span>). <span class=\"greek\">φαίνοντος</span> <span class=\"greek\">ἤδη</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὄρθρου</span> AcPl Ha 4, 3 (v. <span class=\"greek\">ὄρθρος</span>).—Do brilho de um mensageiro celestial AcPl Ha 3, 28; 31; 36.</p><p class=\"entry-text\">ⓑ Pass., em sentido at., de luz e suas fontes, brilhar, resplandecer (Is 60:2) <span class=\"greek\">ἐφάνη</span> <span class=\"greek\">φῶς</span> <span class=\"greek\">μέγα</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">σπηλαίῳ</span> GJs 19:2 (JosAs 14:3 <span class=\"greek\">φῶς</span> <span class=\"greek\">ἀνεκλάλητον</span>) de estrelas, em linguagem figurada Phil 2:15 (TestJob 31:5). De relâmpago como portento (X., Cyr. 1, 6, 1) Mt 24:27. De luz Rv 18:23 (v.l. <span class=\"greek\">φανῇ</span>). De uma estrela, aparecer Mt 2:7 (FBoll, ZNW 18, 1918, 45f); GJs 21:2 codd. Do dia (Appian, Iber. 35 §143 <span class=\"greek\">φαινομένης</span> <span class=\"greek\">ἡμέρας</span>) Rv 8:12.</p><p class=\"entry-text\">② Tornar-se visível, aparecer, pass. <span class=\"greek\">φαίνομαι</span> com sentido at./intr.</p><p class=\"entry-text\">ⓐ Aparecer, ser ou tornar-se visível, ser revelado <span class=\"greek\">τότε</span> <span class=\"greek\">ἐφάνη</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ζιζάνια</span> Mt 13:26 (cf. 2 Macc 1:33 <span class=\"greek\">τό</span> <span class=\"greek\">ὕδωρ</span> <span class=\"greek\">ἐφάνη</span>). <span class=\"greek\">τά</span> <span class=\"greek\">ἔργα</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀνθρώπων</span> 2 Cl 16:3. <span class=\"greek\">τό</span> <span class=\"greek\">σημεῖον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">υἱοῦ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἀνθρώπου</span> Mt 24:30. Cf. D 16:6. <span class=\"greek\">ἀτμὶς</span> <span class=\"greek\">φαινομένη</span> (oposto a <span class=\"greek\">ἀφανιζομένη</span>) Js 4:14. Cf. Hv 3, 2, 6a. <span class=\"greek\">ὁ</span> <span class=\"greek\">ἀσεβὴς</span> <span class=\"greek\">ποῦ</span> <span class=\"greek\">φανεῖται</span>; que será do ímpio? 1 Pt 4:18 (Pr 11:31). <span class=\"greek\">οὐδέποτε</span> <span class=\"greek\">ἐφάνη</span> <span class=\"greek\">οὕτως</span> nunca se viu (=aconteceu) nada semelhante Mt 9:33. <span class=\"greek\">τὸ</span> <span class=\"greek\">φαινόμενον</span> aquilo que é visível (Philo, Rer. Div. Her. 270) IRo 3:3a. <span class=\"greek\">τὰ</span> <span class=\"greek\">φαινόμενά</span> <span class=\"greek\">σου</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">πρόσωπον</span> tudo o que é visível diante de tua face (oposto a <span class=\"greek\">τὰ</span> <span class=\"greek\">ἀόρατα</span>) IPol 2:2. <span class=\"greek\">φαινόμενα</span> coisas que aparecem Hb 11:3 (Ar. 1, 5 <span class=\"greek\">πάντων</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">φαινομένων</span>; Ath. 5, 2; cf. Sext. Emp., Hypotyp. 1, 138). Ign. explica: serei um verdadeiro crente <span class=\"greek\">ὅταν</span> <span class=\"greek\">κόσμῳ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">φαίνωμαι</span> quando já não estiver visivelmente presente no mundo (porque fui devorado pelas feras) IRo 3:2. Um jogo de palavras visa esclarecer isto: também Cristo, pelo fato de estar <span class=\"greek\">ἐν</span> <span class=\"greek\">πατρί</span> e, portanto, já não estar visivelmente presente no mundo, <span class=\"greek\">μᾶλλον</span> <span class=\"greek\">φαίνεται</span> é tanto mais claramente visível como aquilo que realmente é, i.e., <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">ἡμῶν</span> 3:3b. <span class=\"greek\">τ̣ὸ̣</span> [<span class=\"greek\">τέλο</span>]<span class=\"greek\">ς</span> (ou: <span class=\"greek\">τ̣ε̣</span>[<span class=\"greek\">λο</span>]<span class=\"greek\">ς</span>) <span class=\"greek\">τῶν</span> <span class=\"greek\">φαινο</span>[<span class=\"greek\">μέ</span>]<span class=\"greek\">νων</span> (oposto a <span class=\"greek\">ἀφανῶν</span>) luz das coisas vistas Ox 1081, 29f (leitura rev.; v. <span class=\"greek\">διέρχομαι</span> 1b<span class=\"greek\">β</span>); <span class=\"greek\">ἡ</span> <span class=\"greek\">πίστ</span>[<span class=\"greek\">ις</span>] <span class=\"greek\">εὑρ</span>[<span class=\"greek\">ετ</span>]<span class=\"greek\">έ̣</span> [<span class=\"greek\">α</span>] <span class=\"greek\">ἡ</span> <span class=\"greek\">φαινομένη</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀ</span>.[ … <span class=\"greek\">ι</span>]<span class=\"greek\">κ̣οῦ</span> <span class=\"greek\">πατρός</span> 32–34 (v. <span class=\"greek\">ἀπατρικός</span>, mas também <span class=\"greek\">ἀγέννητος</span>, sendo a restauração preferida <span class=\"greek\">ἀγ</span>[<span class=\"greek\">εννή</span>]<span class=\"greek\">τ̣ου</span> com base no copta).</p><p class=\"entry-text\">ⓑ Fazer sua aparição, mostrar-se (Diod S 4, 6, 5 <span class=\"greek\">θεὸν</span> <span class=\"greek\">φαίνεσθαι</span> <span class=\"greek\">παρ</span>’ <span class=\"greek\">ἀνθρώποις</span>; 5, 2, 4 [divindade]; Chariton 5, 7, 10 <span class=\"greek\">φάνηθι</span>, <span class=\"greek\">δαῖμον</span> <span class=\"greek\">ἀγαθέ</span>; Sb 8141, 24 [inscr. I a.C.] <span class=\"greek\">δαίμονος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀγαθοῦ</span> <span class=\"greek\">υἱὸς</span> … <span class=\"greek\">ἐφάνη</span>; ParJer 7:20 <span class=\"greek\">θεὸς</span> … <span class=\"greek\">ἐφάνη</span> <span class=\"greek\">ἡμῖν</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">αἰέτου</span> <span class=\"greek\">τούτου</span>; SibOr 5, 152; Just., A I, 63, 10; <span class=\"greek\">ἐφάνη</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> … <span class=\"greek\">ἄλλως</span> <span class=\"greek\">ἄλλοις</span> Iren. 1, 10, 3 [Harv. I, 95, 9]; Did., Gen. 225, 13; <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰησοῦ</span> … <span class=\"greek\">φαινομένου</span> Just., D. 88, 8) Hv 1, 4, 3. Elias (Jos., Ant. 8, 319) <span class=\"greek\">ἐφάνη</span> fez sua aparição (como precursor do reino de Deus, Mal 3:22. Algumas pessoas consideram que Jesus é Elias que voltou) Lk 9:8. <span class=\"greek\">ἕως</span> <span class=\"greek\">ἐφάνη</span> <span class=\"greek\">βρέφος</span> até que a criança (Jesus) apareceu (em referência ao seu nascimento numa caverna) GJs 19:2. Do primeiro advento de Jesus Cristo, que vem de fora de nosso mundo B 14:5; IMg 6:1; Dg 11:2; também com dat. (X., Cyr. 1, 6, 43; Lucian, Dial. Deor. 20, 5; Ael. Aristid. 51, 25 K.=27 p. 540 D.: <span class=\"greek\">ἡ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">ἐφάνη</span> <span class=\"greek\">μοι</span>) <span class=\"greek\">κόσμῳ</span> 11:3. Do Senhor ressuscitado, com dat. Mk 16:9 (Just., D. 67, 7) <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἀποστόλοις</span>. De um anjo, com dat. (2 Macc 3:33; 10:29) Mt 1:20 (GJs 14:2); 2:13, 19 (cf. Alcaeus L-P. [escólio sobre Nicander, Ther. 613 p. 48 Keil]: <span class=\"greek\">φανῆναι</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Ἀπόλλωνα</span> <span class=\"greek\">καθ</span>’ <span class=\"greek\">ὕπνους</span>; Jos., C. Ap. 1, 289 <span class=\"greek\">κατὰ</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ὕπνους</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">῏Ισις</span> <span class=\"greek\">ἐφάνη</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">Ἀ</span>., Ant. 7, 147; 8, 196). <span class=\"greek\">ὄπως</span> <span class=\"greek\">φανῶσιν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἀνθρώποις</span> para serem vistos pelas pessoas Mt 6:5; com part. para denotar o papel que se representa diante das pessoas (Hyperid., Fgm. 70, 1; Lucian, Dial. Deor. 4, 1; Ael. Aristid. 47 p. 428 D.) <span class=\"greek\">νηστεύοντες</span> como estando em jejum v. 16; cf. 18 (B-D-F §414, 3).—Do Anticristo <span class=\"greek\">φανήσεται</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">υἱὸς</span> <span class=\"greek\">θεοῦ</span> aparecerá (da mesma maneira) como filho de Deus D 16:4.—De pessoas terrenas: <span class=\"greek\">ὅπου</span> <span class=\"greek\">ἄν</span> <span class=\"greek\">φανῇ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐπίσκοπος</span>, <span class=\"greek\">ἐκεῖ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πλῆθος</span> <span class=\"greek\">ἔστω</span> ISm 8:2. De participação numa reunião <span class=\"greek\">διὰ</span> <span class=\"greek\">τί</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐφάνης</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">συνόδῳ</span> <span class=\"greek\">ἡμῶν</span> GJs 15:1. <span class=\"greek\">Παῦλος</span> <span class=\"greek\">φανεῖς</span> <span class=\"greek\">πᾶσι</span> <span class=\"greek\">εἶπεν</span> Paulo mostrou-se (depois de seu martírio) a todos e disse AcPl Ha 11, 5.</p><p class=\"entry-text\">③ Tornar-se conhecido, ser reconhecido, ser manifesto, ser revelado, pass. <span class=\"greek\">φαίνομαι</span> com sentido at./intr.</p><p class=\"entry-text\">ⓐ Com nom. predicativo <span class=\"greek\">εἰ</span> <span class=\"greek\">ἦσαν</span>, <span class=\"greek\">ἐφαίνοντο</span> <span class=\"greek\">ἂν</span> <span class=\"greek\">κλάδοι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σταυροῦ</span> se eles (os falsos mestres) fossem realmente (plantação de Deus), apareceriam como ramos da cruz ITr 11:2. <span class=\"greek\">οὐ</span> <span class=\"greek\">φαίνονται</span> não são manifestos Hs 3:2ab, 3ab. <span class=\"greek\">ἡ</span> <span class=\"greek\">ἁμαρτία</span> <span class=\"greek\">ἵνα</span> <span class=\"greek\">φανῇ</span> <span class=\"greek\">ἁμαρτία</span> para que o pecado fosse reconhecido como pecado Ro 7:13.</p><p class=\"entry-text\">ⓑ Aparecer aos olhos do espírito, ser revelado <span class=\"greek\">ὅπερ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">φανήσεται</span> <span class=\"greek\">πρὸ</span> <span class=\"greek\">προσώπου</span> <span class=\"greek\">ἡμῶν</span>, <span class=\"greek\">ἐξ</span> <span class=\"greek\">ὧν</span> <span class=\"greek\">ἀγαπῶμεν</span> <span class=\"greek\">αὐτόν</span> o que também será revelado diante de nossa face pelo fato de amarmos (o Senhor) IEph 15:3.</p><p class=\"entry-text\">④ Ser conhecido pela aparência em oposição à realidade subjacente, aparecer como algo, parecer ser algo, pass. <span class=\"greek\">φαίνομαι</span> com sentido at./intr. precisado por nom. predicativo (X., Cyr. 1, 4, 19; Cebes 5, 1; Arrian, Anab. 4, 30, 4 <span class=\"greek\">πιστὸς</span> <span class=\"greek\">ἐφαίνετο</span>=mostrou-se digno de confiança; TestReub 5:7; Iren. 5, 1, 2 [Harv. II 315, 5]; Theoph. Ant. 3, 7 [p. 218, 5]) <span class=\"greek\">φαίνονται</span> <span class=\"greek\">ὡραῖοι</span> Mt 23:27. <span class=\"greek\">ἵνα</span> <span class=\"greek\">ἡμεῖς</span> <span class=\"greek\">δόκιμοι</span> <span class=\"greek\">φανῶμεν</span> 2 Cor 13:7. Com dat. de pessoa, parecer algo a alguém (Lucian, Dial. Mort. 25, 1; TestAbr A 20 p. 103, 7 [Stone p. 54]) <span class=\"greek\">φαίνεσθε</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἀνθρώποις</span> <span class=\"greek\">δίκαιοι</span> Mt 23:28 (cf. Pr 21:2). Com <span class=\"greek\">ἐνώπιόν</span> <span class=\"greek\">τινος</span> em vez do dat.: <span class=\"greek\">ἐφάνησαν</span> <span class=\"greek\">ἐνώπιον</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">ὡσεὶ</span> <span class=\"greek\">λῆρος</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ῥήματα</span> <span class=\"greek\">ταῦτα</span> Lk 24:11.—Seguido de <span class=\"greek\">ὡς</span> parecer como se (TestJos 3:4) Hv 3, 2, 6b; Hs 9, 9, 7.</p><p class=\"entry-text\">⑤ Produzir uma impressão na mente, ter a aparência, parecer, freq. com ênfase no aspecto de decisão suscitado pelas circunstâncias; pass. <span class=\"greek\">φαίνομαι</span> com sentido at./intr., com dat. e inf. (Hom. et al.) <span class=\"greek\">οἱ</span> <span class=\"greek\">τοιοῦτοι</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">εὐσυνείδητοί</span> <span class=\"greek\">μοι</span> <span class=\"greek\">εἶναι</span> <span class=\"greek\">φαίνονται</span> IMg 4. Com dat. e part. <span class=\"greek\">φαίνεσθέ</span> <span class=\"greek\">μοι</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">ἀνθρώπους</span> <span class=\"greek\">ζῶντες</span> ITr 2:1. <span class=\"greek\">τί</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">φαίνεται</span>; que vos parece? qual é vossa decisão? Mk 14:64. <span class=\"greek\">ἐάν</span> <span class=\"greek\">σοι</span> <span class=\"greek\">φανῇ</span> se te parecer bem Hv 2, 3, 4 (segundo CTurner, JTS 21, 1920, 198, um latinismo: si tibi videtur. Cf. POxy 811 [I d.C.] <span class=\"greek\">εἴ</span> <span class=\"greek\">σοι</span> <span class=\"greek\">φαίνεται</span>). Sem dat. (Jos., C. Ap. 1, 12; Just., D. 91, 4) <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">φαίνεται</span> <span class=\"greek\">κεκομμένον</span> <span class=\"greek\">ἀπ</span>’ <span class=\"greek\">αὐτοῦ</span> nada parece ter sido cortado dela (a árvore) ou aparentemente nada foi cortado dela (cf. Aristoxenus, Fgm. 83 <span class=\"greek\">φαίνεται</span> <span class=\"greek\">Ὄλυμπος</span> <span class=\"greek\">αὐξήσας</span> <span class=\"greek\">μουσικήν</span>=O. aparentemente enriqueceu a música) Hs 8, 3, 1 (<span class=\"greek\">φαίνεται</span> com acus. e inf. Demetrius: 722 Fgm. 5 Jac.).—B. 1045f.—DELG. M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0374-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φάλεκ</h1><div class=\"entry-meta\"><span>nome próprio masculino indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Φάλεκ</span> (também <span class=\"greek\">Φαλέκ</span>, <span class=\"greek\">Φαλέγ</span>, <span class=\"greek\">Φάλεχ</span> 1 Ch 1:25 B; hebr. <span class=\"hebrew\" dir=\"rtl\">פֶּלֶג</span>, em pausa <span class=\"hebrew\" dir=\"rtl\">פָּֽלֶג</span>, Gen 10:25 al.), <span class=\"greek\">ὁ</span>, indecl. (em Joseph. <span class=\"greek\">Φάλεγος</span>, <span class=\"greek\">ου</span> [Ant. 1, 148]) Pelegue, filho de Héber e pai de Reú (Gen 11:16–19; 1 Ch 1:25), na genealogia de Jesus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:35</a>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0374-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φανεροποιέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φανεροποιέω</span> 1 aor. <span class=\"greek\">ἐφανεροποίησα</span> (Hephaestion Astr. [IV d.C.] 3, 37; v. Cat. Cod. Astr. V/3, 85 linha 11; escólio sobre Aristoph., Eq. 1253; Joannes Sardianus, Comm. in Aphthonii Progymn. ed. HRabe 1928 p. 161, 23; papiros desde VI d.C.) revelar, dar a conhecer <span class=\"greek\">τὶ</span> algo <span class=\"greek\">τὴν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κόσμου</span> <span class=\"greek\">σύστασιν</span> 1 Cl 60:1. Hs 4, 2 <span class=\"greek\">πᾶσι</span> <span class=\"greek\">φανεροποιηθήσονται</span> dos justos no mundo vindouro (v.l. <span class=\"greek\">φανερωθήσονται</span>).—DELG s.v. <span class=\"greek\">φαίνω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0374-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φανερός, ά, όν</h1><div class=\"entry-meta\"><span>adjetivo; substantivado</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φανερός</span>, <span class=\"greek\">ά</span>, <span class=\"greek\">όν</span> (<span class=\"greek\">φαίνομαι</span>; Pind., Hdt.+; inscr., papiros, LXX; En 9:5; TestSol; TestAsh 2:3; ParJer 6:25; EpArist, Philo, Joseph., Ar., Just., Tat.)</p><p class=\"entry-text\">① Adj. relativo a ser evidente, de modo a ser prontamente conhecido, visível, claro, claramente perceptível, aberto, manifesto, evidente, conhecido <span class=\"greek\">τὰ</span> <span class=\"greek\">φανερὰ</span> <span class=\"greek\">ἕργα</span> (oposto a <span class=\"greek\">κρύφια</span>) 2 Cl 16:3. Empregado com <span class=\"greek\">εἶναι</span> (Diod, S. 18, 55, 2 <span class=\"greek\">φανεροῦ</span> <span class=\"greek\">ὄντος</span> <span class=\"greek\">ὅτι</span>=visto que era claro que) <span class=\"greek\">οἱ</span> <span class=\"greek\">καρποὶ</span> <span class=\"greek\">φανεροὶ</span> <span class=\"greek\">ἔσονται</span> Hs 4:3; cf. 4:4. <span class=\"greek\">φ</span>. <span class=\"greek\">ἔσονται</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">δουλεύοντες</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> 4:2. <span class=\"greek\">φανερόν</span> (-<span class=\"greek\">ά</span>) <span class=\"greek\">ἐστιν</span> Ro 1:19 (<span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτοῖς</span>; v. <span class=\"greek\">ἐν</span> 8); Gal 5:19; 1J 3:10 (<span class=\"greek\">ἐν</span> <span class=\"greek\">τούτῳ</span> por isto); Hm 11:10; outras passagens com dat. de pessoa (TestSol 13:2 C) 1 Ti 4:15; B 8:7 (oposto a <span class=\"greek\">σκοτεινά</span>). Sem cópula, que deve ser suprida: com <span class=\"greek\">ὅτι</span> (X., Mem. 3, 9, 2; Teles p. 12, 4; 7; TestAsh 2:3; Iren., 1, 4, 4 [Harv. I, 37, 8]) <span class=\"greek\">πᾶσιν</span> <span class=\"greek\">φανερόν</span> Ac 4:16 (D tem a cópula e, ao mesmo tempo, o comp.: <span class=\"greek\">φανερώτερόν</span> <span class=\"greek\">ἐστιν</span> é bastante conhecido). <span class=\"greek\">φανερὸν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">δένδρον</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">καρποῦ</span> <span class=\"greek\">αὐτοῦ</span> a árvore é conhecida por seu fruto (cf. Mt 12:33) IEph 14:2 (Vi. Aesopi G, 3 P. <span class=\"greek\">φανερὸς</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὄψεως</span>=claramente reconhecível por sua aparência).—Empregado com <span class=\"greek\">γίνεσθαι</span> (BGU 1141, 41 [14 a.C.]; Appian, Bell. Civ. 2, 46 §187 <span class=\"greek\">τοῦ</span> <span class=\"greek\">κακοῦ</span> <span class=\"greek\">φανεροῦ</span> <span class=\"greek\">γενομένου</span>; 1 Macc 15:9; 2 Macc 1:33; ParJer 6:25; Jos., Ant. 2, 270; 6, 238; Just., A 1, 63, 6) <span class=\"greek\">φανερὸν</span> <span class=\"greek\">ἐγένετο</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄνομα</span> <span class=\"greek\">αὐτοῦ</span> Mk 6:14. Cf. Lk 8:17a (oposto a <span class=\"greek\">κρυπτόν</span>); 1 Cor 3:13; 11:19; 14:25; Hs 9, 12, 3; com dat. de pessoa acrescentado (Ael. Aristid. 29, 24 K.=40 p. 758 D.: <span class=\"greek\">φανεροὶ</span> <span class=\"greek\">πᾶσι</span> <span class=\"greek\">γίγνεσθαι</span>; Just., A I, 23, 1) Ac 7:13. <span class=\"greek\">ὥστε</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">δεσμούς</span> <span class=\"greek\">μου</span> <span class=\"greek\">φανεροὺς</span> <span class=\"greek\">γενέσθαι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὅλῳ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πραιτωρίῳ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">λοιποῖς</span> <span class=\"greek\">πᾶσιν</span> Phil 1:13.—Empregado com <span class=\"greek\">ποιεῖν</span> (Hyperid. 4, 1; Menand., Epitr. 495 S. [319 Kö.]; IBM III, 482 A, 13f; POxy 928, 7; PTebt 333, 12; 2 Macc 12:41; Just., A II, 15, 2; Theoph. Ant. 2, 3 [p. 94, 13]) tornar (<span class=\"greek\">τι</span> algo) conhecido (Jos., Ant. 12, 189; 204) 1 Cl 21:7; GJs 5:1. <span class=\"greek\">τινά</span> tornar alguém conhecido como aquilo que realmente é, revelar a identidade de alguém (Jos., Ant. 3, 73; Just., D. 8, 4) Mt 12:16; Mk 3:12.</p><p class=\"entry-text\">② Subst. <span class=\"greek\">τὸ</span> <span class=\"greek\">φανερόν</span> aquilo que está exposto à vista ou ao conhecimento geral, (em) público, conhecimento público (Hyperid. 1, 13, 11 <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">φ</span>. <span class=\"greek\">φέρειν</span> [cf. Just. A I, 15, 3 <span class=\"greek\">εἰς</span> <span class=\"greek\">φανερὸν</span> … <span class=\"greek\">φέρειν</span>]; Polyb. 2, 46, 1; Just. A I, 17, 4 <span class=\"greek\">εἰς</span> <span class=\"greek\">φανερὸν</span> <span class=\"greek\">τιθέντων</span>), <span class=\"greek\">εἰς</span> <span class=\"greek\">φανερὸν</span> <span class=\"greek\">ἐλθεῖν</span> vir à luz Mk 4:22; Lk 8:17b (um provérbio? Constant. Manasse 7, 34f H.: <span class=\"greek\">ἐστὶ</span> <span class=\"greek\">σκότιον</span> <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">ὅπερ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">φῶς</span> <span class=\"greek\">οὐχ</span> <span class=\"greek\">ἥκει</span>, <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔστι</span> <span class=\"greek\">κρύφιον</span> <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">ὸ̔</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">γνῶσιν</span> <span class=\"greek\">φθάνει</span> ‘nada há nas trevas que não venha à luz, e nada oculto que não se torne conhecido’. <span class=\"greek\">εἰς</span> <span class=\"greek\">φ</span>. <span class=\"greek\">ἐλέγχειν</span> Hippol., Ref. 8, 20, 4). <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">φανερῷ</span> (oposto a <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κρυπτῷ</span> como Ctesias: 688 Fgm. 13, 12 p. 460 Jac.) Mt 6:4 v.l., 6 v.l., 18 v.l. (cf. Aeneas Tact. 426; Jos., Ant. 4, 34); precedido de art. e empregado como adj. <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">φανερῷ</span> <span class=\"greek\">Ἰουδαῖος</span> o judeu que o é exteriormente em razão de ser circuncidado Ro 2:28a; cf. b.—B. 1233. DELG s.v. <span class=\"greek\">φαίνω</span> B. Schmidt, Syn. III 418–34. Cf. <span class=\"greek\">δῆλος</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0374-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φανερόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φανερόω</span> fut. <span class=\"greek\">φανερώσω</span>; 1 aor. <span class=\"greek\">ἐφανέρωσα</span>; perf. <span class=\"greek\">πεφανέρωκα</span>. Pass.: 1 fut. <span class=\"greek\">φανερωθήσομαι</span>; 1 aor. <span class=\"greek\">ἐφανερώθην</span>; perf. <span class=\"greek\">πεφανέρωμαι</span> (cf. <span class=\"greek\">φανέρωσις</span>; Hdt. 6, 122 [uma interpolação tardia]; Dionys, Hal. 10, 37; Cass. Dio 59, 18; 77, 15; PGoodsp 15, 19 [IV d.C.]; Jer 40:6; TestSol; TestAbr B; JosAs 12:2; AscIs 3; 13; Philo; Jos., Ant. 20, 76; Just., Tat., Mel.)</p><p class=\"entry-text\">① Fazer tornar-se visível, revelar, expor publicamente (com ênfase relativamente maior no aspecto sensorial do que no cognitivo, como em 2 abaixo. Mas as distinções nem sempre são claras)</p><p class=\"entry-text\">ⓐ De pessoas</p><p class=\"entry-text\"><span class=\"greek\">α</span>. At., do Senhor ressuscitado J 21:1a; cf. 1b.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Pass. com sentido intr., mostrar-se ou revelar-se, ser revelado, aparecer <span class=\"greek\">τινί</span> a alguém Hs 2:1. <span class=\"greek\">ἡμᾶς</span> <span class=\"greek\">φανερωθῆναι</span> <span class=\"greek\">δεῖ</span> <span class=\"greek\">ἔμπροσθεν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">βήματος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Χριστοῦ</span> 2 Cor 5:10.—Esp. de Cristo (Just., A I, 56, 1; Mel., P. 43, 302. Do Logos <span class=\"greek\">φανερωθεὶς</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἀνθρώποις</span> Iren. 3, 11, 8 [Harv. II 47, 8]) de sua aparição no mundo <span class=\"greek\">ἐφανερώθη</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">σαρκί</span> 1 Ti 3:16 (ALau, Manifest in Flesh, The Epiphany Christology of the Pastoral Epistles ’96); cf. B 5:6; 6:7, 9, 14; 12:10. <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ἀνθρωπίνως</span> <span class=\"greek\">φανερουμένου</span> IEph 19:3.—Hb 9:26; 1 Pt 1:20; 1J 1:2ab. A finalidade da aparição é expressa por uma oração com <span class=\"greek\">ἵνα</span> 1J 3:5, 8; B 14:5; 2 Cl 14:2.—Da aparição do Senhor ressuscitado <span class=\"greek\">τοῖς</span> <span class=\"greek\">μαθηταῖς</span> J 21:14; cf. Mk 16:12 (<span class=\"greek\">ἐν</span> <span class=\"greek\">ἑτέρᾳ</span> <span class=\"greek\">μορφῇ</span>), 14. Sem dat. B 15:9. Do segundo advento Col 3:4a; 1 Pt 5:4; 1J 2:28; 3:2b.—<span class=\"greek\">ὑμεῖς</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">αὐτῷ</span> (i.e., Cristo por ocasião de seu retorno) <span class=\"greek\">φανερωθήσεσθε</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">δόξῃ</span> Col 3:4b. Da comunidade cristã <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐκκλησία</span> <span class=\"greek\">πνευματικὴ</span> <span class=\"greek\">οὖσα</span> <span class=\"greek\">ἐφανερώθη</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">σαρκὶ</span> <span class=\"greek\">Χριστοῦ</span> 2 Cl 14:3.</p><p class=\"entry-text\">ⓑ De coisas, pass. com sentido intr. (Jos, Ant. 17, 194; Hippol., Ref. 9, 5, 1; Theoph. Ant. 2, 4 [p. 102, 22]) tornar-se visível ou conhecido, ser revelado Mk 4:22; 2 Cor 4:10f; Eph 5:13f; Rv 3:18. Seguido de interrogativa indireta 1J 3:2a.</p><p class=\"entry-text\">② Fazer tornar-se conhecido, revelar, mostrar, dar a conhecer</p><p class=\"entry-text\">ⓐ De coisas</p><p class=\"entry-text\"><span class=\"greek\">α</span>. At. (PBrem 53, 26 [114 d.C.]; Hippol., Ref. 6, 47, 4) <span class=\"greek\">ἐφανέρωσεν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">δόξαν</span> <span class=\"greek\">αὐτοῦ</span> J 2:11 (TestAbr B 14 p. 118, 18 [Stone p. 84] <span class=\"greek\">τὴν</span> <span class=\"greek\">σαπρότητα</span>; JosAs 12:2 <span class=\"greek\">τὰ</span> <span class=\"greek\">ἀφανῆ</span>; Jos., Vi. 231 <span class=\"greek\">φ</span>. <span class=\"greek\">τὴν</span> <span class=\"greek\">ὀργήν</span>). <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">ἐφανέρωσεν</span> Deus lhes mostrou o que se pode conhecer acerca de Deus Ro 1:19 (v. AKlöpper, ZWT 47, 1904, 169–80). Cf. 1 Cor 4:5; Tit 1:3; 2 Cl 20:5; Dg 8:11 (com <span class=\"greek\">ἀποκαλύπτειν</span>); 9:1, 2b; 11:5; IRo 8:2. <span class=\"greek\">φανεροῦν</span> <span class=\"greek\">τινι</span> <span class=\"greek\">ἀποκάλυψιν</span> comunicar uma revelação a alguém Hv 3, 1, 2. <span class=\"greek\">κατὰ</span> <span class=\"greek\">ἀποκάλυψιν</span> <span class=\"greek\">φανεροῦν</span> <span class=\"greek\">τινι</span> dar a conhecer ou mostrar a alguém numa revelação MPol 22:3. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">σοὶ</span> … <span class=\"greek\">φανερώσει</span> <span class=\"greek\">κύριος</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">λύτρον</span> em relação a ti o Senhor revelará a salvação GJs 7:2. <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὀσμὴν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γνώσεως</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">φανεροῦντι</span> <span class=\"greek\">δι</span>’ <span class=\"greek\">ἡμῶν</span> a Deus, que por nosso intermédio dá a conhecer a fragrância do conhecimento referente a ele (prov. Cristo, mas v. REB e NRSV, de Deus) 2 Cor 2:14. <span class=\"greek\">πάντα</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">πατὴρ</span> <span class=\"greek\">φανεροῖ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">υἱοῦ</span> <span class=\"greek\">Ἰησοῦ</span> B 12:8. (<span class=\"greek\">ὁ</span> <span class=\"greek\">κύριος</span>) <span class=\"greek\">πεφανέρωκεν</span> <span class=\"greek\">ἡμῖν</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">προφητῶν</span> <span class=\"greek\">ὅτι</span> <span class=\"greek\">κτλ</span>. 2:4.—Dar a conhecer oralmente, ensinar <span class=\"greek\">ἐφανέρωσά</span> <span class=\"greek\">σου</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄνομα</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἀνθρώποις</span> J 17:6 (embora aqui o ensino seja acompanhado de uma revelação que se dá por meio de um ato.—HHuber, D;. Begriff der Offenbarung im Joh. ev. ’34). <span class=\"greek\">ἐν</span> <span class=\"greek\">παντὶ</span> <span class=\"greek\">φανερώσαντες</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">πᾶσιν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ὑμᾶς</span> de toda maneira tornamos isto (i.e., <span class=\"greek\">τὴν</span> <span class=\"greek\">γνῶσιν</span>) claro para vós, à vista de todos os homens 2 Cor 11:6. Cf. Col 4:4.—Revelar <span class=\"greek\">τοὺς</span> <span class=\"greek\">γάμους</span> GJs 15:2, 4.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Pass. com sentido intr. (Jos, Ant. 17, 194; Hippol., Ref. 9, 5, 1; Theoph. Ant. 2, 4 [p. 102, 22]) tornar-se de conhecimento público, ser revelado, tornar-se conhecido J 3:21; 9:3; Ro 16:26; 2 Cor 7:12; Col 1:26; 2 Ti 1:10; Hb 9:8; 1J 4:9; Rv 15:4; B 7:7; IEph 19:2. Seguido de interrogativa indireta 1J 3:2a. Seguido de <span class=\"greek\">ὅτι</span> Dg 9:2a. <span class=\"greek\">χωρὶς</span> <span class=\"greek\">νόμου</span> <span class=\"greek\">δικαιοσύνη</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">πεφανέρωται</span> independentemente da lei, foi revelada a justiça que procede de Deus Ro 3:21.</p><p class=\"entry-text\">ⓑ De pessoas</p><p class=\"entry-text\"><span class=\"greek\">α</span>. At. <span class=\"greek\">ἑαυτόν</span> mostrar-se ou revelar-se: de Deus (Philo, Leg. All. 3, 47) <span class=\"greek\">διὰ</span> <span class=\"greek\">Ἰησοῦ</span> IMg 8:2.—De Cristo <span class=\"greek\">φανέρωσον</span> <span class=\"greek\">σεαυτὸν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κόσμῳ</span> J 7:4. Diferentemente, <span class=\"greek\">ἐφανέρωσεν</span> <span class=\"greek\">ἑαυτὸν</span> <span class=\"greek\">εἶναι</span> <span class=\"greek\">υἱὸν</span> <span class=\"greek\">θεοῦ</span> revelou que era o Filho de Deus B 5:9.—Expor <span class=\"greek\">ἐὰν</span> <span class=\"greek\">αὐτὴν</span> <span class=\"greek\">φανερώσω</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">υἱοῖς</span> <span class=\"greek\">Ἰσραήλ</span> se eu expuser (Maria) aos israelitas GJs 14:1.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Pass. com sentido intr., ser dado a conhecer <span class=\"greek\">ἵνα</span> <span class=\"greek\">φανερωθῇ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">Ἰσραήλ</span> J 1:31. <span class=\"greek\">θεῷ</span> <span class=\"greek\">πεφανερώμεθα</span> somos bem conhecidos de Deus 2 Cor 5:11a, cf. 11b; 11:6 v.l. (por <span class=\"greek\">φανερώσαντες</span>). Com <span class=\"greek\">ὅτι</span> subsequente, tornar-se conhecido, demonstrar-se (que) 3:3; 1J 2:19 (logicamente impessoal, como <span class=\"greek\">ἠκούσθη</span> em Mk 2:1).—MBockmuehl, Das Verb <span class=\"greek\">φανερόω</span> im NT: BZ 32, ’88, 87–99.—DELG s.v. <span class=\"greek\">φαίνω</span>. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0374-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φανερῶς</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φανερῶς</span> adv. de <span class=\"greek\">φανερός</span> (Aeschyl., Hdt. et al.; papiros; 2 Macc 3:28; TestSol, Philo, Joseph., Just., Mel., HE 4, 26, 5)</p><p class=\"entry-text\">① À vista de todos, abertamente, publicamente Mk 1:45. (Oposto a <span class=\"greek\">ἐν</span> <span class=\"greek\">κρυπτῷ</span>; cf. Jos., Ant. 5, 213 <span class=\"greek\">κρυπτῶς</span> … <span class=\"greek\">φ</span>.; TestJos 4:2) J 7:10. (Oposto a <span class=\"greek\">λάθρᾳ</span>, como em Pla., Symp. 182d) IPhld 6:3; GMary 463 linha 13f.</p><p class=\"entry-text\">② Com nitidez visual, claramente, distintamente (Jos., Vi. 277) <span class=\"greek\">ἰδεῖν</span> Ac 10:3.</p><p class=\"entry-text\">③ De maneira prontamente compreensível, claramente, manifestamente, <span class=\"greek\">δειχθῆναι</span> Dg 11:2.—O neut. do comp. como adv. <span class=\"greek\">φανερώτερον</span> (ainda) mais claramente <span class=\"greek\">λέγειν</span> B 13:4 (Tat. 4, 3; Ath. 2, 2).—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0374-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φανέρωσις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φανέρωσις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (cf. <span class=\"greek\">φανερόω</span>; Aristot., De Plant. 2, 1; 9; Herm. Wr. 11, 1; Cat. Cod. Astr. VII 229, 23; 230, 20; VIII/1 p. 165, 6; Just., D. 49, 3 al.; <span class=\"greek\">ἡ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σωτῆρος</span> <span class=\"greek\">φ</span>. Hippol., Ref. 8, 10, 1; papiros VIII d.C.) manifestação, anúncio, com gen. objetivo <span class=\"greek\">ἡ</span> <span class=\"greek\">φαν</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀληθείας</span> a proclamação aberta da verdade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 4:2</a>. A sintaxe do gen. em <span class=\"greek\">ἡ</span> <span class=\"greek\">φανέρωσις</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πνεύματος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:7</a> não pode ser determinada com certeza. Seja o gen. subjetivo ou objetivo, a expressão significa o mesmo que <span class=\"greek\">χάρισμα</span>.—DELG s.v. <span class=\"greek\">φαίνω</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0374-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φανός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φανός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">φάος</span> ‘luz’; Aristoph., X.+; UPZ 5, 18 [163 a.C.]; 6, 15; empréstimo na literatura rabínica) uma luz portátil, lâmpada, orig.=‘tocha’ e, mais tarde, para grande contrariedade dos aticistas (Hesych. s.v.; Phryn. p. 59 Lob.; Athen. 15, 58 p. 699dff; Pollux 6, 103; 10, 116),=lanterna (<span class=\"greek\">λυχνοῦχος</span>); assim <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.3\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:3</a> ao lado de <span class=\"greek\">λαμπάς</span> (q.v. 1).—DELG s.v. <span class=\"greek\">φάε</span> C. Frisk s.v. <span class=\"greek\">φάος</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0374-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φανουήλ, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Φανουήλ</span>, <span class=\"greek\">ὁ</span> indecl. (<span class=\"hebrew\" dir=\"rtl\">פְּנוּאֵל</span>; 1 Ch 4:4; 8:25 v.l.; cf. Gen 32:32, nome de lugar; Philo, Conf. Lingu. 129) Fanuel, pai de Hanna(h)/Ana, profetisa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:36</a>.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0374-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαντάζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φαντάζω</span> (Aeschyl., Hdt.+; Sir 34:5; Wsd 6:16; TestSim 4:9) na voz at. ‘tornar visível’, mas geralmente na pass. com sentido intr., tornar-se visível, aparecer (Philo), esp. de fenômenos extraordinários (na natureza etc.; cf. Apollon. Rhod. 4, 1283; <span class=\"greek\">Περὶ</span> <span class=\"greek\">ὕψους</span> 15, 4; 7; PGM 7, 888) <span class=\"greek\">τὸ</span> <span class=\"greek\">φανταζόμενον</span> visão, espetáculo, de uma teofania (como Ps.-Aristot., Mirabilia 108 de Atena; Herodian 8, 3, 9 de Apolo) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.21\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:21</a>.—DELG s.v. <span class=\"greek\">φαίνω</span> B 10. M-M. TW.</p></section></article>"};